llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "In patients with alcoholic cirrhosis, tolfenamic acid had an absolute oral bioavailability of about 100% after 100 mg p.o. compared with i.v., directly supporting high F in cirrhosis.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "Bumetanide, a loop diuretic with a sulfonamide-containing polar framework, showed 95% oral bioavailability in patients with cirrhosis, supporting high F for the query under the same condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Isradipine, although only 16-19% bioavailable in healthy volunteers, increased to 37% in cirrhosis, demonstrating that cirrhosis can raise oral bioavailability above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Safinamide had 95% absolute oral bioavailability in healthy subjects, providing additional high-transfer evidence that small-molecule drugs with amide/aromatic structures can be almost completely absorbed.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a pyridine-sulfonylurea loop diuretic (torasemide-like). The most transferable cirrhosis-specific evidence—bumetanide 95%, tolfenamic acid ~100%, and isradipine 37%—all support oral bioavailability ≥20%. Additional high-bioavailability analogues reinforce this direction, and no affirmative low-F evidence under cirrhosis was found.",
  "evidence_gaps": [
    "No direct torasemide bioavailability record is present in the supplied evidence; prediction relies on high-transfer analogues.",
    "Only three analogues have cirrhosis-specific bioavailability data; the remaining evidence comes from healthy subjects or other conditions.",
    "Cirrhosis severity and portosystemic shunting could alter first-pass metabolism, but the available cirrhosis data point to preserved or increased bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

